<?= $this->extend('layouts/management') ?><?= $this->section('content') ?>
<div class="metrics"><?php foreach(['products'=>'Semua Produk','categories'=>'Kategori','available'=>'Tersedia','unavailable'=>'Tidak Tersedia'] as $k=>$label): ?><div><span><?= $label ?></span><strong><?= (int)$counts[$k] ?></strong></div><?php endforeach ?></div>
<section class="surface"><div class="toolbar"><form method="get" class="filters"><input class="form-control" name="q" placeholder="Cari nama produk…" aria-label="Cari produk" value="<?= esc($q,'attr') ?>"><select class="form-select" name="category" aria-label="Kategori"><option value="">Semua Kategori</option><?php foreach($categories as $c): ?><option value="<?= esc($c['id'],'attr') ?>" <?= $category===$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach ?></select><select class="form-select" name="inventory" aria-label="Stok"><option value="">Semua Stok</option><option value="low" <?= $inventory==='low'?'selected':'' ?>>Stok Rendah (1–5)</option><option value="empty" <?= $inventory==='empty'?'selected':'' ?>>Stok Habis</option></select><button class="btn btn-primary">Cari</button><a href="<?= site_url('admin/products') ?>">Reset</a></form><a class="btn btn-primary" href="<?= site_url('admin/products/create') ?>">+ Tambah Produk</a></div>
<div class="table-responsive"><table class="table align-middle"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><div class="product-cell"><img src="<?= esc($p['image'],'attr') ?>" alt=""><strong><?= esc($p['name']) ?></strong></div></td><td><?= esc($p['category_name']) ?></td><td>Rp <?= number_format($p['price'],0,',','.') ?></td><td><span class="badge text-bg-<?= $p['stock']===0||$p['stock']==='0'?'danger':($p['stock']<=5?'warning':'light') ?>"><?= (int)$p['stock'] ?></span></td><td><span class="badge text-bg-<?= $p['status']==='active'?'success':'secondary' ?>"><?= $p['status']==='active'?'Tersedia':'Tidak Tersedia' ?></span></td><td class="actions"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('admin/products/edit/'.$p['id']) ?>">Edit / Detail</a><form method="post" action="<?= site_url('admin/products/delete/'.$p['id']) ?>" onsubmit="return confirm('Hapus produk ini secara permanen?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Hapus</button></form></td></tr><?php endforeach ?><?php if(!$products): ?><tr><td colspan="6" class="text-center py-5">Tidak ada produk yang sesuai. Ubah filter atau tambahkan produk baru.</td></tr><?php endif ?></tbody></table></div><?= $pager->only(['q','category','inventory'])->links('default','se') ?></section><?= $this->endSection() ?>